handle_os_error:
; Called after every key read (carry set when the read returned an OZ error, A = error code).
; RC_Draw: the screen was corrupted by another application - redefine window 1 and redraw.
; RC_Quit: free the three memory pools and leave with OS_Bye.
; Other codes are passed back to the caller.
        ret     nc
        push    af
        ld      a,(line_buffer_bank)
        ld      b,a
        ld      c,$02
        rst     $20
        defb    Os_mpb
        pop     af
        push    af
        cp      RC_Draw
        jr      z,L_D09F
        cp      RC_Quit
        jr      z,L_D0B4
        pop     af
        ret
